52	function sanitizeMainTheatreState(
53	  state: Record<string, unknown> | null,
54	): Record<string, unknown> | null {
55	  if (!state) return null;
56	  const sheetsByIdValue = state.sheetsById;
57	  if (
58	    sheetsByIdValue == null ||
59	    typeof sheetsByIdValue !== "object" ||
60	    Array.isArray(sheetsByIdValue)
61	  ) {
62	    return state;
63	  }
64	  const sheetsById = sheetsByIdValue as Record<string, unknown>;
65	  const nextSheetsById: Record<string, unknown> = {};
66	  MAIN_THEATRE_SHEET_IDS.forEach((sheetId) => {
67	    if (!Object.prototype.hasOwnProperty.call(sheetsById, sheetId)) return;
68	    nextSheetsById[sheetId] = sheetsById[sheetId];
69	  });
70	  return {
71	    ...state,
72	    sheetsById: nextSheetsById,
73	  };
74	}
