441	  private _resolveSheetLength(
442	    sheetId: MainTheatreSheetId,
443	    sequence: TheatreSequencePort,
444	  ): number {
445	    const directLength =
446	      typeof sequence.length === "number" ? sequence.length : null;
447	    if (
448	      directLength != null &&
449	      Number.isFinite(directLength) &&
450	      directLength > 0
451	    ) {
452	      return directLength;
453	    }
454	    return this._readSheetLengthFromState(sheetId);
455	  }
456	
457	  private _readSheetLengthFromState(sheetId: MainTheatreSheetId): number {
458	    if (!this._stateSource) return 0;
459	    const sheetsById = this._readRecord(this._stateSource.sheetsById);
460	    if (!sheetsById) return 0;
461	    const sheetState = this._readRecord(sheetsById[sheetId]);
462	    if (!sheetState) return 0;
463	    const sequence = this._readRecord(sheetState.sequence);
464	    if (!sequence) return 0;
465	    const length = sequence.length;
466	    if (typeof length !== "number" || !Number.isFinite(length) || length <= 0) {
467	      return 0;
468	    }
469	    return length;
470	  }
