479	  private _resolveCameraPreviewRange(
480	    sheetId: MainTheatreSheetId,
481	    sheetLength: number,
482	  ): MainTheatrePlaybackRange | null {
483	    return this._resolvePreviewRangeByTrackFilter(
484	      sheetId,
485	      sheetLength,
486	      (debugName) =>
487	          MAIN_CAMERA_TRACK_DEBUG_NAMES.some((path) =>
488	            debugName.includes(path),
489	          ),
490	    );
491	  }
492	
493	  private _resolvePreviewRangeByTrackFilter(
494	    sheetId: MainTheatreSheetId,
495	    sheetLength: number,
496	    shouldIncludeTrack?: (debugName: string) => boolean,
497	  ): MainTheatrePlaybackRange | null {
498	    const tracksByObject = this._readSheetTracksByObject(sheetId);
499	    const objectTracks = tracksByObject?.[MAIN_THEATRE_OBJECT_ID];
500	    if (!objectTracks || typeof objectTracks !== "object") return null;
501	    const trackData = (objectTracks as Record<string, unknown>).trackData;
502	    if (!trackData || typeof trackData !== "object") return null;
503	    let minPosition = Number.POSITIVE_INFINITY;
504	    let maxPosition = Number.NEGATIVE_INFINITY;
505	    Object.values(trackData as Record<string, unknown>).forEach(
506	      (trackState) => {
507	        if (!trackState || typeof trackState !== "object") return;
508	        const debugName = (trackState as Record<string, unknown>).__debugName;
509	        if (
510	          shouldIncludeTrack &&
511	          (typeof debugName !== "string" || !shouldIncludeTrack(debugName))
512	        ) {
513	          return;
514	        }
515	        const keyframes = (trackState as Record<string, unknown>).keyframes;
516	        if (!Array.isArray(keyframes)) return;
517	        const positions = keyframes
518	          .map((keyframe) => {
519	            if (!keyframe || typeof keyframe !== "object") return null;
520	            const position = (keyframe as Record<string, unknown>).position;
521	            return typeof position === "number" ? position : null;
522	          })
523	          .filter(
524	            (position): position is number =>
525	              typeof position === "number" && Number.isFinite(position),
526	          );
527	        if (positions.length < 2) return;
528	        minPosition = Math.min(minPosition, ...positions);
529	        maxPosition = Math.max(maxPosition, ...positions);
530	      },
531	    );
532	    if (!Number.isFinite(minPosition) || !Number.isFinite(maxPosition))
533	      return null;
534	    if (maxPosition <= minPosition) return null;
535	    return {
536	      start: this._clampPosition(minPosition, sheetLength),
537	      end: this._clampPosition(maxPosition, sheetLength),
538	    };
539	  }
540	
541	  private _readSheetTracksByObject(
542	    sheetId: MainTheatreSheetId,
543	  ): Record<string, unknown> | null {
544	    if (!this._stateSource) return null;
545	    const sheetsById = this._readRecord(this._stateSource.sheetsById);
546	    if (!sheetsById) return null;
547	    const sheetState = this._readRecord(sheetsById[sheetId]);
548	    if (!sheetState) return null;
549	    const sequence = this._readRecord(sheetState.sequence);
550	    if (!sequence) return null;
551	    return this._readRecord(sequence.tracksByObject);
552	  }
553	
554	  private _readRecord(value: unknown): Record<string, unknown> | null {
555	    if (value == null || typeof value !== "object" || Array.isArray(value)) {
556	      return null;
557	    }
558	    return value as Record<string, unknown>;
559	  }
560	
561	  private _clampPosition(position: number, length: number): number {
562	    if (!Number.isFinite(length) || length <= 0) return 0;
563	    if (!Number.isFinite(position)) return 0;
564	    if (position <= 0) return 0;
565	    if (position >= length) return length;
566	    return position;
567	  }
568	
569	  private _resolveDebugTrackSnapshots(
570	    sheetId: MainTheatreSheetId,
571	    sheetPosition: number,
572	  ): MainSceneDebugSnapshot["tracks"] {
573	    const tracksByObject = this._readSheetTracksByObject(sheetId);
574	    const objectTracks = tracksByObject?.[MAIN_THEATRE_OBJECT_ID];
575	    if (!objectTracks || typeof objectTracks !== "object") return [];
576	    const trackData = (objectTracks as Record<string, unknown>).trackData;
577	    if (!trackData || typeof trackData !== "object") return [];
578	    const snapshots: MainSceneDebugTrackSnapshot[] = [];
579	    Object.values(trackData as Record<string, unknown>).forEach(
580	      (trackState) => {
581	        if (!trackState || typeof trackState !== "object") return;
582	        const debugName = (trackState as Record<string, unknown>).__debugName;
583	        if (
584	          typeof debugName !== "string" ||
585	          !MAIN_CAMERA_TRACK_DEBUG_NAMES.some((path) =>
586	            debugName.includes(path),
587	          )
588	        ) {
589	          return;
590	        }
591	        const keyframes = (trackState as Record<string, unknown>).keyframes;
592	        if (!Array.isArray(keyframes) || keyframes.length === 0) return;
593	        const positions = keyframes
594	          .map((keyframe) => {
595	            if (!keyframe || typeof keyframe !== "object") return null;
596	            const position = (keyframe as Record<string, unknown>).position;
597	            return typeof position === "number" && Number.isFinite(position)
598	              ? position
599	              : null;
600	          })
601	          .filter((position): position is number => position != null);
602	        if (positions.length === 0) return;
603	        snapshots.push({
604	          track: debugName.replace("orbitCamera:", ""),
605	          keyframeCount: positions.length,
606	          fromKeyframeIndex: this._resolveDebugFromKeyframeIndex(
607	            positions,
608	            sheetPosition,
609	          ),
610	          toKeyframeIndex: this._resolveDebugToKeyframeIndex(
611	            positions,
612	            sheetPosition,
613	          ),
614	        });
615	      },
616	    );
617	    return snapshots;
618	  }
619	
620	  private _resolveDebugFromKeyframeIndex(
621	    positions: readonly number[],
622	    sheetPosition: number,
623	  ): number | null {
624	    if (positions.length === 0) return null;
625	    for (let index = positions.length - 1; index >= 0; index -= 1) {
626	      if (sheetPosition >= positions[index]) return index;
627	    }
628	    return null;
629	  }
630	
631	  private _resolveDebugToKeyframeIndex(
632	    positions: readonly number[],
633	    sheetPosition: number,
634	  ): number | null {
635	    for (let index = 0; index < positions.length; index += 1) {
636	      if (sheetPosition <= positions[index]) return index;
637	    }
638	    return null;
639	  }
