178	function remapWhyProgress(value: number, start: number, end: number): number {
179	  if (value <= start) return 0;
180	  if (value >= end) return 1;
181	  return (value - start) / Math.max(end - start, Number.EPSILON);
182	}
183	
184	function easeOutWhyProgress(value: number): number {
185	  const clampedValue = Helpers.clamp01(value);
186	  return 1 - Math.pow(1 - clampedValue, 3);
187	}
