2	import type {
3	  RevealObserveOptions,
4	  TextRevealOptions,
5	  TextRevealInitOptions,
6	} from "../types/component.types.js";
7	import { DOM_CONFIG, MASKING } from "../config/dom.config.js";
8	import { ObserveManager } from "../manager/ObserveManager.js";
9	import { Animation } from "./Animation.js";
10	
11	const BR_PATTERN = /<br\s*\/?>/gi;
12	const MASKING_DISABLED_CLASS = "is-text-reveal-disabled";
13	
14	export class TextReveal extends Animation {
15	  private static readonly MASK_READY_CLASS = "is-mask-ready";
16	  private static _observeFrameId: number | null = null;
17	  private static readonly _observeManager = new ObserveManager();
18	
19	  static riseUp(
20	    target: string | Element | Element[],
21	    options: TextRevealOptions = {},
22	  ): void {
23	    const revealClass = options.revealClass ?? MASKING.inviewClass;
24	    const elements = TextReveal.resolveManagedElements(target).filter(
25	      (element): element is HTMLElement =>
26	        element instanceof HTMLElement && !element.classList.contains(revealClass),
27	    );
28	    if (elements.length === 0) return;
29	    elements.forEach((element) => {
30	      element.classList.remove(MASKING.downClass);
31	      element.classList.remove(MASKING.hiddenClass);
32	      element.classList.add(revealClass);
33	    });
34	  }
35	
36	  static setVisibleOn(
37	    target: string | Element | Element[],
38	    options: TextRevealOptions = {},
39	  ): void {
40	    TextReveal.riseUp(target, options);
41	  }
42	
43	  static setVisibleOff(
44	    target: string | Element | Element[],
45	    options: TextRevealOptions = {},
46	  ): void {
47	    const revealClass = options.revealClass ?? MASKING.inviewClass;
48	    const elements = TextReveal.resolveManagedElements(target).filter(
49	      (element): element is HTMLElement => element instanceof HTMLElement,
50	    );
51	    if (elements.length === 0) return;
52	    elements.forEach((element) => {
53	      element.classList.remove(revealClass, MASKING.visibleClass);
54	      element.classList.remove(MASKING.hiddenClass);
55	      element.classList.remove(MASKING.downClass);
56	      void element.getBoundingClientRect();
57	      element.classList.add(MASKING.downClass);
58	    });
59	  }
60	
61	  static prepare(
62	    target: string | Element | Element[],
63	    options: TextRevealOptions = {},
64	  ): Element[] {
65	    const revealClass = options.revealClass ?? MASKING.inviewClass;
66	    const elements = TextReveal.resolveManagedElements(target).filter(
67	      (element): element is HTMLElement => element instanceof HTMLElement,
68	    );
69	    if (elements.length === 0) return [];
70	    elements.forEach((element) => {
71	      element.classList.remove(
72	        revealClass,
73	        MASKING.visibleClass,
74	        MASKING.downClass,
75	      );
76	    });
77	    return elements;
78	  }
79	
80	  static observe(
81	    target: string | Element | Element[],
82	    options: RevealObserveOptions = {},
83	  ): void {
84	    if (typeof document === "undefined") return;
85	    const revealClass = options.inviewClass ?? MASKING.inviewClass;
86	    const targets = TextReveal._resolveObserveTargets(target, options);
87	    if (targets.length === 0) return;
88	    const onEnter =
89	      options.onEnter ??
90	      ((element: Element) =>
91	        TextReveal.riseUp(element, { revealClass }));
92	    TextReveal._observeFrameId = window.requestAnimationFrame(() => {
93	      TextReveal._observeFrameId = window.requestAnimationFrame(() => {
94	        TextReveal._observeFrameId = null;
95	        TextReveal._observeManager.observe(
96	          targets,
97	          {
98	            onEnter,
99	            onLeave: options.onLeave,
100	          },
101	          options,
102	        );
103	      });
104	    });
105	  }
106	
107	  static override resolveElements(
108	    target: string | Element | Element[],
109	  ): Element[] {
110	    if (target == null) return [];
111	    const resolve = (el: Element | null | undefined): Element[] => {
112	      if (el == null || typeof el.matches !== "function") return [];
113	      if (el.matches(MASKING.selector)) return [el];
114	      return [el, ...Array.from(el.querySelectorAll<Element>(MASKING.selector))];
115	    };
116	
117	    if (typeof target === "string") {
118	      const list = document.querySelectorAll(target);
119	      return Array.from(list).flatMap(resolve);
120	    }
121	    const arr = super.resolveElements(target);
122	    return arr.flatMap(resolve);
123	  }
124	
125	  static wrap(
126	    selector = `.${MASKING.wrapTargetClass}`,
127	    root?: ParentNode | null,
128	  ): void {
129	    if (typeof document === "undefined") return;
130	    const wrapperClass = MASKING.selector.slice(1);
131	    const scope = root ?? document;
132	    const elements = scope.querySelectorAll<HTMLElement>(selector);
133	    elements.forEach((el) => {
134	      if (el.querySelector(MASKING.selector)) {
135	        el.classList.add(TextReveal.MASK_READY_CLASS);
136	        return;
137	      }
138	      const hasBr = el.querySelector("br") !== null;
139	      if (hasBr) {
140	        TextReveal.wrapMultiLine(el, wrapperClass);
141	      } else {
142	        TextReveal.wrapSingleLine(el, wrapperClass);
143	      }
144	      el.classList.add(TextReveal.MASK_READY_CLASS);
145	    });
146	  }
147	
148	  private static wrapSingleLine(el: HTMLElement, wrapperClass: string): void {
149	    const outer = document.createElement("span");
150	    outer.className = wrapperClass;
151	    const inner = document.createElement("span");
152	    inner.className = MASKING.lineClass;
153	    while (el.firstChild) inner.appendChild(el.firstChild);
154	    outer.appendChild(inner);
155	    el.appendChild(outer);
156	  }
157	
158	  private static wrapMultiLine(el: HTMLElement, wrapperClass: string): void {
159	    const segments = el.innerHTML
160	      .split(BR_PATTERN)
161	      .map((s) => s.trim())
162	      .filter(Boolean);
163	    el.innerHTML = "";
164	    segments.forEach((segmentHtml) => {
165	      const outer = document.createElement("span");
166	      outer.className = wrapperClass;
167	      const inner = document.createElement("span");
168	      inner.className = MASKING.lineClass;
169	      inner.innerHTML = segmentHtml;
170	      outer.appendChild(inner);
171	      el.appendChild(outer);
172	    });
173	  }
174	
175	  
176	
177	
178	
179	  static init(options: TextRevealInitOptions = {}): void {
180	    if (typeof document === "undefined") return;
181	
182	    TextReveal.dispose();
183	
184	    TextReveal.wrap(`.${MASKING.wrapTargetClass}`, options.root);
185	    if (!MASKING.enabled) {
186	      document.documentElement.classList.add(MASKING_DISABLED_CLASS);
187	      return;
188	    }
189	    document.documentElement.classList.remove(MASKING_DISABLED_CLASS);
190	
191	    const selector = options.selector ?? MASKING.selector;
192	    const excludeSelectors =
193	      options.excludeSelectors ?? DOM_CONFIG.maskingExcludeSelectors ?? [];
194	    const inviewClass = options.inviewClass ?? MASKING.inviewClass;
195	    const targets = TextReveal.resolveTargets(
196	      selector,
197	      excludeSelectors,
198	      options.root,
199	    );
200	    if (targets.length === 0) return;
201	    TextReveal.prepare(targets, { revealClass: inviewClass });
202	    TextReveal.observe(targets, { ...options, inviewClass });
203	  }
204	
205	  static dispose(): void {
206	    if (TextReveal._observeFrameId != null) {
207	      window.cancelAnimationFrame(TextReveal._observeFrameId);
208	      TextReveal._observeFrameId = null;
209	    }
210	    TextReveal._observeManager.dispose();
211	    if (typeof document !== "undefined") {
212	      document.documentElement.classList.remove(MASKING_DISABLED_CLASS);
213	    }
214	  }
215	
216	  private static resolveTargets(
217	    selector: string,
218	    excludeSelectors: string[],
219	    root?: ParentNode | null,
220	  ): Element[] {
221	    const scope = root ?? document;
222	    const all = Array.from(scope.querySelectorAll(selector));
223	    const excludeRoots = excludeSelectors
224	      .map((sel) => scope.querySelector(sel))
225	      .filter((el): el is Element => el != null);
226	    const scoped =
227	      excludeRoots.length === 0
228	        ? all
229	        : all.filter((el) =>
230	      excludeRoots.every((root) => !root.contains(el)),
231	    );
232	    return [...new Set(scoped)];
233	  }
234	
235	  private static resolveManagedElements(
236	    target: string | Element | Element[],
237	  ): Element[] {
238	    if (typeof document === "undefined") return [];
239	    if (!MASKING.enabled) return [];
240	    if (target == null) return [];
241	    return TextReveal.resolveElements(target);
242	  }
243	
244	  private static _resolveObserveTargets(
245	    target: string | Element | Element[],
246	    options: RevealObserveOptions,
247	  ): Element[] {
248	    if (typeof target !== "string") {
249	      return TextReveal.resolveManagedElements(target);
250	    }
251	    const excludeSelectors =
252	      options.excludeSelectors ?? DOM_CONFIG.maskingExcludeSelectors ?? [];
253	    return TextReveal.resolveTargets(target, excludeSelectors, options.root);
254	  }
255	}
